import { $, expect, driver } from '@wdio/globals';
import { byText, byTextContains, byTextMatches, scrollToText, pageCounter } from '../../helpers/ui.ts';
import { skipWith, shown, ensureNusach } from '../_lib/app-0710.ts';
import {
  cardRe, scrollToMatch, readField, setField, saveDraft, approveDraft, qaMarker, recordingSummary,
  REC_UPLOAD_BTN, REC_PENDING, REC_APPROVE_BTN, REC_NOT_MATCHING,
} from '../_lib/admin.ts';
import { pickFileInSystemPicker, removeRecordingWithDialog } from '../_lib/app-1310.ts';
import {
  goHome, openProfile, waitHuman, openCatalogPrayer, goPage, button, saveArtifact, labelOf, nodes,
} from '../_lib/readiness-1910.ts';

const APPROVER = process.env.QA_APPROVER || 'בודק QA';
const K = {
  3: { title: 'המעריב ערבים', mp3: process.env.QA_MP3_K3 || 'arvit-ashk-k3' },
  4: { title: 'אהבת עולם', mp3: process.env.QA_MP3_K4 || 'arvit-ashk-k4' },
} as const;
type Kn = keyof typeof K;
/** 8 полей «עריכת קטע» (порядок сверху вниз, как на экране 19.10). */
const TEXT_FIELDS = ['כותרת הקטע', 'טקסט התפילה', 'הערה לקטע (לא חובה)', 'קרדיט למקור', 'הפניה במקור', 'מהדורה', 'רישיון'] as const;
const REC_FIELD = 'מי הקליט';
type Snap = Record<string, string>;

async function adminEntryVisible() {
  try { await openProfile(); await scrollToText('ממשק ניהול התוכן', 6); return true; } catch { return false; }
}
async function openAdminPrayerScreen() {
  await openProfile();
  await (await scrollToText('ממשק ניהול התוכן')).click();
  await (await byText('ניהול תכני תפילה')).waitForDisplayed({ timeout: 20000 });
  await (await scrollToMatch(cardRe('ערבית', 'אשכנז'))).click();
  await (await byTextMatches('\\d+ מתוך \\d+ קטעים מאושרים')).waitForExist({ timeout: 20000 });
}
async function openK(n: Kn) {
  await openAdminPrayerScreen();
  await (await scrollToMatch(`(?s)${n}, ${K[n].title},.*`, 20)).click();
  await (await byText('עריכת קטע')).waitForDisplayed({ timeout: 20000 });
}
const norm = (label: string, v: string | null | undefined) => {
  const s = String(v ?? '');
  return s === label ? '' : s;
};
async function snapshot(n: Kn): Promise<Snap> {
  await openK(n);
  const s: Snap = {};
  for (const f of [...TEXT_FIELDS, REC_FIELD]) s[f] = norm(f, await readField(f).catch(() => ''));
  return s;
}
/** Загрузить MP3 из «Файлы» и утвердить запись. */
async function uploadAndApprove(n: Kn) {
  await openK(n);
  await setField(REC_FIELD, APPROVER);
  if (driver.isIOS) await driver.execute('mobile: hideKeyboard', {}).catch(() => {});
  await (await scrollToText(REC_UPLOAD_BTN)).click();
  const cell = await $(`-ios predicate string:type == "XCUIElementTypeCell" AND label BEGINSWITH "${K[n].mp3}"`);
  if (driver.isIOS && (await cell.waitForExist({ timeout: 20000 }).then(() => true, () => false))) await cell.click();
  else await pickFileInSystemPicker(`${K[n].mp3}.mp3`);
  await (await byTextContains(REC_PENDING)).waitForExist({ timeout: 180000 });
  await (await scrollToText(REC_APPROVE_BTN)).click();
  await (await byTextContains('אושרה על ידי')).waitForExist({ timeout: 30000 });
}
async function userPage(n: number) {
  await openCatalogPrayer('ערבית');
  await ensureNusach('אשכנזי');
  await goPage(n);
}
const playing = () => shown(button('השהה'));

describe('Готовность 19.10 — админка: текст и озвучка (ערבית אשכנז קטע 3/4)', () => {
  before(async function () {
    this.timeout(1000000);
    if (process.env.QA_ADMIN_MANUAL !== '1') skipWith(this, 'нужен вход клиента (админ) человеком — запуск с QA_ADMIN_MANUAL=1');
    if (!(await adminEntryVisible())) await waitHuman('войдите в приложение аккаунтом КЛИЕНТА (в профиле должен быть «ממשק ניהול התוכן»)', adminEntryVisible);
  });
  after(async () => { await goHome().catch(() => {}); });

  it('RD-07a MP3 на קטע 3 и 4 → утверждение → у пользователя «הקראה: … · אושרה על ידי …», «השמע»→«השהה», стоп в конце קטע, «קודם» во время игры останавливает; правка текста → сразу у пользователя, запись «לא תואמת» и не предлагается; всё возвращено #6a86f7eda7b2 #6a86f7ed9d38 #a5decf4a F-91 F-92 AC2/AC4 F-102 AC4/AC5 @admin @data @manual-check', async function () {
    this.timeout(3600000);
    await openAdminPrayerScreen();
    const sumBefore = await recordingSummary();
    const orig: Record<number, Snap> = { 3: await snapshot(3), 4: await snapshot(4) };
    const snapFile = saveArtifact(`admin-arvit-ash-k3-k4-${Date.now()}.json`, orig);
    console.log(`[RD-07] снимок полей до правок: ${snapFile}; сводка «הקראות הקטעים»: ${JSON.stringify(sumBefore)}`);
    if (orig[3]['טקסט התפילה'].length < 100) throw new Error('текст קטע 3 не прочитан — правку не начинаем');
    const marker = qaMarker('RD07');
    try {
      // 1. Записи на קטע 3 и 4.
      await uploadAndApprove(3);
      await uploadAndApprove(4);

      // 2. Пользователь: стр. 3 — своя запись, играет и останавливается в конце קטע без перелистывания.
      await userPage(3);
      await scrollToText('האזן להקראה');
      const line = await labelOf((await byTextContains('הקראה:')) as unknown as WebdriverIO.Element);
      expect(line).toContain(APPROVER);
      expect(line).toContain('אושרה על ידי');
      await (await button('השמע')).click();
      await driver.waitUntil(playing, { timeout: 10000, timeoutMsg: '«השמע» не сменилась на «השהה»' });
      await driver.waitUntil(async () => !(await playing()), { timeout: 120000, interval: 1000, timeoutMsg: 'запись стр. 3 не остановилась' });
      expect(await pageCounter()).toMatch(/^3 מתוך /);
      expect(await shown(button('השמע'))).toBe(true);

      // 3. Стр. 4 — своя запись; «קודם» во время игры останавливает.
      await goPage(4);
      await scrollToText('האזן להקראה');
      await (await button('השמע')).click();
      await driver.waitUntil(playing, { timeout: 10000, timeoutMsg: 'стр. 4: нет «השהה»' });
      await (await button('קודם')).click();
      await driver.waitUntil(async () => (await pageCounter()).startsWith('3 מתוך'), { timeout: 15000 });
      const resumed = await driver.waitUntil(playing, { timeout: 4000 }).then(() => true, () => false);
      expect(resumed).toBe(false);

      // 4. F-102 AC4: правка текста קטע 3 + «אישור ופרסום» → у пользователя сразу новый текст; запись «לא תואמת» (F-92 AC2).
      await openK(3);
      await setField('טקסט התפילה', `${orig[3]['טקסט התפילה']} (בדיקת QA)`);
      await saveDraft();
      await setField('שם המאשר', APPROVER);
      await approveDraft(marker);
      await openK(3);
      await scrollToText(REC_NOT_MATCHING);
      await userPage(3);
      await expect(byTextContains('(בדיקת QA)')).toBeExisting({ wait: 20000 });
      await expect(byTextContains(`אושר על ידי ${APPROVER}`)).toBeExisting();     // F-102 AC5
      await scrollToText('האזן להקראה');
      await expect(byTextContains('אין הקראה לקטע הזה')).toBeExisting();
      expect(await (await button('השמע')).isEnabled()).toBe(false);
    } finally {
      // 5. Возврат: текст посимвольно (7 полей), записи удалены, «מי הקליט» как было.
      const now3 = await snapshot(3);
      const diff = TEXT_FIELDS.filter((f) => now3[f] !== orig[3][f]);
      if (diff.length) {
        for (const f of diff) await setField(f, orig[3][f]);
        await saveDraft();
        await setField('שם המאשר', APPROVER);
        await approveDraft(qaMarker('RD07-restore'));
      }
      for (const n of [3, 4] as Kn[]) {
        await openK(n);
        await removeRecordingWithDialog();
        if (norm(REC_FIELD, await readField(REC_FIELD).catch(() => '')) !== orig[n][REC_FIELD]) await setField(REC_FIELD, orig[n][REC_FIELD]);
      }
      for (const n of [3, 4] as Kn[]) {
        const s = await snapshot(n);
        const bad = [...TEXT_FIELDS, REC_FIELD].filter((f) => s[f] !== orig[n][f]);
        if (bad.length) throw new Error(`קטע ${n}: не вернулись поля ${bad.join(', ')} — восстановить вручную из ${snapFile}`);
      }
      await openAdminPrayerScreen();
      const sumAfter = await recordingSummary();
      expect(sumAfter.none).toBe(sumBefore.none);
      expect(sumAfter.pending).toBe(sumBefore.pending);
    }
  });

  it('RD-07b «עריכת קטע»: есть карточка «מיקום ומחיקה» с «מחיקת הקטע» (раньше — только добавление в конец) #16933ca6 @admin @prod-safe @passed-2110', async () => {
    await openK(3);
    const labels = (await nodes()).map((x) => x.label).join('\n');
    // 19.10: удаления/перестановки не было. 21.10 (#16933ca6 עבר QA): в «עריכת קטע» карточка «מיקום ומחיקה» с «מחיקת הקטע».
    // Полный сценарий (место, порядок, удаление, утверждение) — qa-2110/q-09 (ברכת הלבנה). Здесь только просмотр קטע 3 (с озвучкой — не трогаем).
    expect(labels).toContain('מיקום ומחיקה');
    expect(labels).toContain('מחיקת הקטע');
  });
});
